setup.test_runlength.py:
from runlength import run_length


def test_collapses_runs():
    assert run_length("aabbbcc") == [("a", 2), ("b", 3), ("c", 2)]


def test_single_characters():
    assert run_length("abc") == [("a", 1), ("b", 1), ("c", 1)]


def test_one_long_run():
    assert run_length("aaaa") == [("a", 4)]


def test_empty_text():
    assert run_length("") == []


def test_runs_are_case_sensitive():
    assert run_length("aAa") == [("a", 1), ("A", 1), ("a", 1)]
